def max_rectangle_area(N, lengths):
    lengths.sort()
    max_area = 0
    for i in range(N-1, 2, -1):
        if lengths[i] >= lengths[0] + lengths[1]:
            break
        for j in range(i-1, 1, -1):
            if lengths[j] * lengths[j] > max_area and lengths[j] < lengths[i]:
                found = False
                k, l = 0, N-1
                while k < j and l > j:
                    if lengths[k] + lengths[l] == lengths[i] - lengths[j]:
                        max_area = lengths[j] * lengths[j]
                        found = True
                        break
                    elif lengths[k] + lengths[l] < lengths[i] - lengths[j]:
                        k += 1
                    else:
                        l -= 1
                if found:
                    break
    return max_area

