import sys

def max_rectangle_area(N, lengths):
    lengths.sort()
    max_area = 0

    # We need to find the largest pair of lengths and the next two larger lengths
    # such that they can form a rectangle
    for i in range(N-3):
        if lengths[i] * lengths[i+1] > max_area:
            for j in range(i+2, N-1):
                if lengths[j] <= lengths[i]:
                    continue
                for k in range(j+1, N):
                    if lengths[k] <= lengths[j]:
                        continue
                    if lengths[j] * lengths[k] > max_area and lengths[i] + lengths[k] == lengths[j] + lengths[i]:
                        max_area = lengths[j] * lengths[k]

    return max_area

