import sys

def max_rectangle_area(sticks):
    sticks.sort()
    n = len(sticks)
    max_area = 0
    for i in range(n-3):
        if sticks[i] + sticks[i+1] <= sticks[-1]:
            continue
        for j in range(i+2, n-1):
            if sticks[j] * 2 > sticks[-2] or sticks[i] + sticks[j] <= sticks[-1]:
                continue
            for k in range(j+1, n):
                if sticks[k] * 2 > sticks[-2] or sticks[i] + sticks[k] <= sticks[-1] or sticks[j] + sticks[k] <= sticks[-1]:
                    continue
                max_area = max(max_area, sticks[i] * sticks[j])
    return max_area

